let lastDay=dateKey();setInterval(()=>{const today=dateKey(),dayChanged=lastDay!==today;if(dayChanged){lastDay=today;filter='all'}if(running()||$('timer-dialog').open||dayChanged){renderToday();if(!$('week-view').hidden)renderWeek();if($('timer-dialog').open)renderTimer()}const active=running();if(active&&!$('timer-dialog').open){const t=state.tasks.find(t=>t.id===active.taskId);document.title=`${clock(daySeconds(today,active.taskId))} · ${t?.name||'Focus'} — MeeeMe`}else if(!active&&!$('timer-dialog').open)document.title='MeeeMe · A little time for yourself'},1000);
