if(document.modelContext?.registerTool){const controller=new AbortController();try{document.modelContext.registerTool({name:'add_daily_task',description:'Save a custom task for today in this browser.',inputSchema:{type:'object',properties:{name:{type:'string',minLength:1,maxLength:100},minutes:{type:'integer',minimum:1,maximum:1440}},required:['name','minutes'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||typeof input.name!=='string'||!input.name.trim()||input.name.length>100||!Number.isInteger(input.minutes)||input.minutes<1||input.minutes>1440)throw new Error('A task name and 1–1440 whole minutes are required.');const id=uid();await change(s=>s.tasks.push({id,name:input.name.trim(),goal:input.minutes,day:dateKey(),groupId:'',tag:'',deleted:false}));return {id,saved:true,day:dateKey()}}},{signal:controller.signal});window.addEventListener('pagehide',()=>controller.abort(),{once:true})}catch{}}
applyTheme(currentTheme);

